16 , y + cell_h // 3 ), record [ \"token\" ], fill = \"black\" , font = font ) draw . line ([( x , y ), ( x + cell_w , y )], fill = \"#dddddd\" ) sheet . save ( out_dir / \"atlas.png\" ) print ( f \" atlas sheet: { out_dir / 'atlas.png' } \" f \"( { sheet . width } x { sheet . height } )\" ) # A second, denser sheet for the prompt. The readable one above is for a # human; a model pays for every pixel, and at ~2,700 px tall the first sheet # costs more image tokens than the page crop it is meant to help with. cols2 , cell_w2 , cell_h2 = 5 , 280 , 62 rows2 = ( len ( manifest ) + cols2 - 1 ) // cols2 tight = Image . new ( \"RGB\" , ( cols2 * cell_w2 , rows2 * cell_h2 + 34 ), \"white\" ) draw2 = ImageDraw . Draw ( tight ) draw2 . text (( 8 , 6 ), \"KEY: each printed symbol of this volume and its token\" , fill = \"black\" , font = head ) for i , record in enumerate ( manifest ): x , y = ( i % cols2 ) * cell_w2 , ( i // cols2 ) * cell_h2 + 34 try : crop = Image . open ( out_dir / record [ \"file\" ]) except Exception : # noqa: BLE001 continue scale = min (( cell_h2 - 10 ) / max ( crop . height , 1 ), 1.6 ) crop = crop . resize (( max ( 1 , int ( crop . width * scale )), max ( 1 , int ( crop . height * scale )))) tight . paste ( crop , ( x + 5 , y + 5 )) draw2 . text (( x + 5 + crop . width + 8 , y + cell_h2 // 3 ), record [ \"token\" ], fill = \"black\" , font = font ) tight . save ( out_dir / \"atlas_prompt.png\" ) print ( f \" prompt sheet: { out_dir / 'atlas_prompt.png' } \" f \"( { tight . width } x { tight . height } , ~ { tight . width * tight . height // 750 } \" f \"image tokens)\" ) def main () -> int : ap = argparse . ArgumentParser ( description = __doc__ , formatter_class = argparse . RawDescriptionHelpFormatter ) ap . add_argument ( \"--scan\" , type = int , default = LEGEND_SCAN ) ap . add_argument ( \"--show\" , action = \"store_true\" , help = \"print the full manifest\" ) args = ap . parse_args () return build ( args . scan , args . show ) if __name__ == \"__main__\" : raise SystemExit ( main ())", "script-utils-lexikon_1910-build_symbol_atlas_de": "TL;DR Cut the German edition's own symbol legend into a labelled atlas (D-92). 1910 register · v1.2.0 · 466 lines · 13 public functions · 19 constants · used by nothing else · utils/lexikon_1910/build_symbol_atlas_de.py load_targets plate_words dark_mask plate_ink drop_rules ink_columns plate_entries body_rows build borrow compose report main HERE ROOT PROFILE OUT_DIR PLATES COLUMNS LEGEND_SCAN RENDER_WIDTH TITLE BLANK_MIN SYMBOL_MAX GLOSS_MIN BAND_INK PAPER_SHARE COLUMN_SHARE RULE_RUN RULE_PAD BORROWED COMPOSED How it works The German twin of build_symbol_atlas . The Spezialortsrepertorium von Böhmen explains its pictograms on the plate Zeichenerklärung , p. XI — scan 0012 of the UBW scan — three columns wide, one symbol to a line with its German meaning beside it, exactly as the Czech Výklad značek does on its p. XI. The German reader is shown its own volume's plate, not the Czech one. The two plates are not the same list: the German one prints 80 symbols, and the three the Czech plate has beyond them — [cooperative] , [port] and [rc-parish-exp] — are not on it (the German volume writes cooperatives as letters only, and a parish expositure as the word Exp. ). The prompt tells the reader that the key \"is the whole of what this volume prints\", so a Czech key would be a false statement to a German reader, three times over. How it works is the Czech builder's, reused rather than copied: the plate is self-labelling, so each printed gloss names its token through the de pictogram rows of institution_abbreviations.csv (whose expansions were read off this same plate), and the layout — symbol band, gutter, gloss — gives the crop. The one difference is the text layer: this PDF has no ALTO, so the words come from the PDF's own positional OCR layer ( pymupdf get_text(\"words\") ), scaled onto a render at the Czech plate's width so the Czech builder's pixel constants keep their meaning. What comes out, in reference/places/symbols/de/ ( de_maehren/ , de_schlesien/ with --volume ): &lt;token&gt;.png one crop per pictogram manifest.csv token, printed gloss, match score, source box atlas.png the crops with their tokens, for a person atlas_prompt.png the dense sheet a reader is sent ( --atlas arms) Usage python utils/lexikon_1910/build_symbol_atlas_de.py python utils/lexikon_1910/build_symbol_atlas_de.py --show python utils/lexikon_1910/build_symbol_atlas_de.py --volume maehren_de # its own plate (D-146) python utils/lexikon_1910/build_symbol_atlas_de.py --volume schlesien_de # composed from Mähren's Functions def load_targets ( volume : str = PROFILE ) -> list [ tuple ] [(token, printed gloss, english, category)] for every German pictogram. The gloss is the expansion plus the qualifier printed with it , which the table keeps in note after the plate reference ( Rotte + Häuser in loserer Verteilung … ). The plate prints both on one entry, and the OCR damages short words worst — it reads Rotte as Hotte — so the long qualifier is what lets the entry be matched at all. Called by utils/lexikon_1910/build_symbol_atlas.py source · lines 93–110 (18 lines) 93 94 95 96 97 98 99 100 101 102 103 104 105 106 107 108 109 110 def load_targets ( volume : str = PROFILE ) -> list [ tuple ]: \"\"\"``[(token, printed gloss, english, category)]`` for every German pictogram. The gloss is the expansion **plus the qualifier printed with it**, which the table keeps in ``note`` after the plate reference (``Rotte`` + ``Häuser in loserer Verteilung …``). The plate prints both on one entry, and the OCR damages short words worst — it reads *Rotte* as ``Hotte`` — so the long qualifier is what lets the entry be matched at all. \"\"\" rows = lxin . load_abbreviations ( bsa . ABBREVIATIONS , lang = \"de\" , volume = volume ) out = [] for a in rows : if a . kind != \"pictogram\" or a . lang != \"de\" or not a . expansion : continue qualifier = a . note . split ( \";\" , 1 )[ 1 ] 